CREATE TABLE IF NOT EXISTS jr_users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('client','operator','admin')), email_verified boolean NOT NULL DEFAULT false, totp_secret text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jr_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES jr_users(id) ON DELETE CASCADE,csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS jr_email_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES jr_users(id) ON DELETE CASCADE,purpose text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS jr_operators(id uuid PRIMARY KEY,user_id uuid UNIQUE NOT NULL REFERENCES jr_users(id),company text NOT NULL,licence text NOT NULL,country text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected')),review_note text,verified_at timestamptz);
CREATE TABLE IF NOT EXISTS jr_aircraft(id uuid PRIMARY KEY,operator_id uuid NOT NULL REFERENCES jr_operators(id),registration text UNIQUE NOT NULL,model text NOT NULL,seats integer NOT NULL CHECK(seats BETWEEN 1 AND 100),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected')),insurance_expires date NOT NULL);
CREATE TABLE IF NOT EXISTS jr_charters(id uuid PRIMARY KEY,operator_id uuid NOT NULL REFERENCES jr_operators(id),aircraft_id uuid NOT NULL REFERENCES jr_aircraft(id),origin text NOT NULL,destination text NOT NULL,departure timestamptz NOT NULL,arrival timestamptz NOT NULL,status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','cancelled')),reference text NOT NULL,CHECK(arrival>departure),CHECK(origin<>destination));
CREATE TABLE IF NOT EXISTS jr_listings(id uuid PRIMARY KEY,operator_id uuid NOT NULL REFERENCES jr_operators(id),aircraft_id uuid NOT NULL REFERENCES jr_aircraft(id),parent_charter_id uuid NOT NULL REFERENCES jr_charters(id),origin text NOT NULL,destination text NOT NULL,departure timestamptz NOT NULL,arrival timestamptz NOT NULL,price_minor bigint NOT NULL CHECK(price_minor>0),currency text NOT NULL CHECK(currency IN ('INR','USD','EUR','GBP','AED')),cancellation_terms text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','rejected','withdrawn','expired')),review_note text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(arrival>departure),CHECK(origin<>destination));
CREATE UNIQUE INDEX IF NOT EXISTS jr_one_active_parent_return ON jr_listings(parent_charter_id) WHERE status IN ('pending','published');
CREATE INDEX IF NOT EXISTS jr_listing_search ON jr_listings(origin,destination,departure) WHERE status='published';
CREATE TABLE IF NOT EXISTS jr_bookings(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES jr_users(id),listing_id uuid NOT NULL REFERENCES jr_listings(id),passengers integer NOT NULL CHECK(passengers>0),status text NOT NULL DEFAULT 'held' CHECK(status IN ('held','confirmed','expired','cancelled','review_required','refund_pending','refunded')),price_minor bigint NOT NULL,currency text NOT NULL,hold_until timestamptz NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE UNIQUE INDEX IF NOT EXISTS jr_one_whole_aircraft_booking ON jr_bookings(listing_id) WHERE status IN ('held','confirmed','review_required','refund_pending');
CREATE TABLE IF NOT EXISTS jr_payments(id uuid PRIMARY KEY,booking_id uuid NOT NULL REFERENCES jr_bookings(id),session_id text UNIQUE,provider text NOT NULL DEFAULT 'stripe',status text NOT NULL DEFAULT 'created',amount_minor bigint NOT NULL,currency text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jr_payment_events(event_id text PRIMARY KEY,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jr_documents(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES jr_users(id),booking_id uuid NOT NULL REFERENCES jr_bookings(id),filename text NOT NULL,mime text NOT NULL,ciphertext bytea NOT NULL,iv bytea NOT NULL,tag bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jr_alerts(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES jr_users(id),origin text NOT NULL,destination text NOT NULL,travel_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,origin,destination,travel_date));
CREATE TABLE IF NOT EXISTS jr_audit(id bigserial PRIMARY KEY,actor_id uuid REFERENCES jr_users(id),action text NOT NULL,target_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());

-- Additive, repeatable upgrade: existing payment records and ciphertext stay intact.
ALTER TABLE jr_payments ADD COLUMN IF NOT EXISTS payment_intent_id text;
ALTER TABLE jr_payments ADD COLUMN IF NOT EXISTS refund_id text;
ALTER TABLE jr_payments ADD COLUMN IF NOT EXISTS refund_status text;
ALTER TABLE jr_payments ADD COLUMN IF NOT EXISTS refund_amount_minor bigint;
CREATE UNIQUE INDEX IF NOT EXISTS jr_payment_intent_unique ON jr_payments(payment_intent_id) WHERE payment_intent_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS jr_refund_unique ON jr_payments(refund_id) WHERE refund_id IS NOT NULL;
